    --关卡阵容信息
    local lineUpInfo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self._curBossPlanVo.range)
    if lineUpInfo then
        lineUpInfo = checkTable(lineUpInfo)
        --只有一波怪
        lineUpInfo = checkTable(lineUpInfo[1])
        self:FillMonstInfo(lineUpInfo)
    end

    CfUtils.FillImage(self.Bg, self._curBossPlanVo.modelId)
end

