function UIWorldBossDetailsDialog:FillMonstInfo(data)
    if not data then
        return
    end
    data = checkTable(data)

    local monsterIds = data.wave1NpcId
    local attributes = data.attribute

    self._followMonsts = {}
    for i = 1, #monsterIds do
        local vo = CardConfMgr:GetInstance():GetMonsterTypeVoById(monsterIds[i])
        if vo then
            --boss
            if checkNumber(vo.monsterClass) == Constants.RoleClass.Elite then
                self:FillBossInfo(vo)
            else
                vo.attribute = attributes[i]
                table.insert(self._followMonsts, vo)
            end
        end
    end
    print(table.dump(data))
    self.LoopView:InitGridView(#self._followMonsts, Bind(self, self.OnRefreshIndex))
end

--小怪刷新
function UIWorldBossDetailsDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell.gameObject.transform:Find("CommonMonstCardNode"), CommonMonstCardNode)
    if scr then
        local data = self._followMonsts[index + 1]
        scr:RefeshMonstHeadIcon(data, cell.gameObject)
    end

    return cell
end

function UIWorldBossDetailsDialog:FillBossInfo(vo)
    if not vo then
        return
    end

    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(vo.skinId)
    CfUtils.FillText(self.BossName, skinVo.name)
    CfUtils.FillText(self.Txtcontent, skinVo.desc2)
    for i = 1, MAXSKILLNUM do
        local num = (i == 1 and "" or i)
        local skillId = vo["atkSkill"..num]
        if checkNumber(skillId) > 0 then

            ---@type SkillCardVo
            local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId)
            if skillCardVo then
                local go = CfUtils.InstantiateGo(self.SkillGroup, self.BossSkills)
                local scr = CfUtils.GetLuaScr(go, UIWorldBossSkillNode)
                if scr then
                    scr:Refresh(skillCardVo)
                end
            end
        end
    end

    ---@type SkillCardVo
    local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(vo["hitSkill"])
    if skillCardVo then
        local go = CfUtils.InstantiateGo(self.SkillGroup, self.BossSkills)
        local scr = CfUtils.GetLuaScr(go, UIWorldBossSkillNode)
        if scr then
            scr:Refresh(skillCardVo)
        end
    end
end

